rows=[]
seen=set()
with open(MASTER, 'r', encoding='utf-8-sig', errors='replace') as f:
    reader=csv.DictReader(f)
    for row in reader:
        seen.add(nt(row.get('Title','')))
        rows.append(row)

added=0
for e in E:
    k=nt(e.get('Title',''))
    if k in seen: continue
    seen.add(k)
    for col in COLUMNS:
        if col not in e or not e[col]:
            e[col]=DEF.get(col,'')
    rows.append(e)
    added+=1

for i,r in enumerate(rows,start=1):
    r['Project_ID']=f'P{i:06d}'

with open(MASTER,'w',newline='',encoding='utf-8') as f:
    writer=csv.DictWriter(f,fieldnames=COLUMNS,extrasaction='ignore')
    writer.writeheader()
    writer.writerows(rows)

from collections import Counter
dc=Counter(r.get('Domain','?') for r in rows)
print(f'Added {added}. Total: {len(rows)}, {len(dc)} domains')
below=[(d,c) for d,c in dc.items() if c<50]
if below:
    print('Still below 50:')
    for d,c in sorted(below,key=lambda x:x[1]):
        print(f'  {d}: {c}')
else:
    print('ALL domains >= 50!')
